    print("Levy a=%.2f lam=%.2f numeric=%.6f exact=%.6f" % (a, lam, num, exact))
    if abs(num - exact) > 1e-3:
        levy_ok = False

# So Laplace transform e^{-alpha sqrt(2 lam)} corresponds to density alpha e^{-alpha^2/2t}/sqrt(2 pi t^3).
